// Minimal JWT-style token: base64(payload).base64(hmac). Real code uses jjwt.
class TokenService {
    private final String secret;
    TokenService(String secret) { this.secret = secret; }

    String issue(String username, String role, long ttlSeconds) {
        long exp = Instant.now().getEpochSecond() + ttlSeconds;
        String payload = username + "|" + role + "|" + exp;
        String p64 = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(payload.getBytes(StandardCharsets.UTF_8));
        return p64 + "." + sign(p64);
    }

    TokenClaims validate(String token) {
        String[] parts = token.split("\\.");
        if (parts.length != 2) throw new InvalidTokenException("malformed token");
        if (!sign(parts[0]).equals(parts[1])) throw new InvalidTokenException("bad signature");
        String payload = new String(Base64.getUrlDecoder().decode(parts[0]), StandardCharsets.UTF_8);
        String[] f = payload.split("\\|");
        long exp = Long.parseLong(f[2]);
        if (Instant.now().getEpochSecond() > exp) throw new InvalidTokenException("token expired");
        return new TokenClaims(f[0], f[1], exp);
    }

    private String sign(String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            return Base64.getUrlEncoder().withoutPadding()
                .encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            throw new InvalidTokenException("signing failed: " + e.getMessage());
        }
    }
}

